    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(tipX, tipY);
    ctx.lineTo(tipX - fx * 13 + fy * 6, tipY - fy * 13 - fx * 6);
    ctx.moveTo(tipX, tipY);
    ctx.lineTo(tipX - fx * 13 - fy * 6, tipY - fy * 13 + fx * 6);
    ctx.stroke();

    // Досягаемость: главное, что нужно видеть перед ударом.
    ctx.lineWidth = 2.5;
    ctx.strokeStyle = '#7fd0ff';
    ctx.beginPath();
    ctx.arc(sx, sy, reach, angle - half, angle + half);
    ctx.stroke();

    ctx.restore();
